constraints:
1 <= N <= 10^{5}
1 <= W <= 10^{5}

expected time complexity: O(NlogN)
expected auxiliary space: O(1)

standard_solution_code:
class Item:

	def __init__(self, val, w):
		self.value = val
		self.weight = w

class Solution:

	def fractionalknapsack(self, W, arr, n):
		arr.sort(key=lambda x: -1 * (x.value / x.weight))
		profit = 0
		for i in range(n):
			v = arr[i].value
			w = arr[i].weight
			if w <= W:
				W -= w
				profit += v
			else:
				profit += W * (v / w)
				W = 0
				break
		return profit
